import json
for acc in ['4DNESWST3UBH','4DNES21D8SP8']:
 d=json.load(open(f'/workspace/{acc}.json'))
 print('\\n==',acc, d.get('biosource',{}).get('display_title'), d.get('experiment_type'))
 def walk(o):
  if isinstance(o,dict):
   if '@id' in o and ('files' in o.get('@id','') or 'File' in o.get('@type',[])):
    yield o
   for v in o.values(): yield from walk(v)
  elif isinstance(o,list):
   for v in o: yield from walk(v)
 seen=set(); files=[]
 for f in walk(d):
  uid=f.get('uuid') or f.get('@id')
  if uid in seen: continue
  seen.add(uid); files.append(f)
 print('files',len(files))
 for f in files[:200]:
  vals={k:f.get(k) for k in ['accession','display_title','file_type','file_format','file_format_type','href','@id','output_type','status','assembly','genome_assembly','track_and_facet_info'] if k in f}
  text=' | '.join(str(vals.get(k,'')) for k in vals)
  if any(s in text.lower() for s in ['loop','peak','cool','mcool','hic','pairs','bedpe','dot']):
   print(vals)
PY"

